mapper.select:
SELECT * FROM adventure_entry
WHERE character_id = #{characterId}::uuid
  AND id != #{id}::uuid
  AND play_date IS NOT NULL
  AND (
      play_date < #{playDate}
      OR (
          play_date = #{playDate}
          AND (created_at, id) < (#{createdAt}, #{id}::uuid)
      )
  )
ORDER BY play_date DESC, created_at DESC, id DESC
LIMIT 1

SELECT * FROM adventure_entry
WHERE character_id = #{characterId}::uuid
  AND id != #{id}::uuid
  AND play_date IS NOT NULL
  AND (
      play_date > #{playDate}
      OR (
          play_date = #{playDate}
          AND (created_at, id) > (#{createdAt}, #{id}::uuid)
      )
  )
ORDER BY play_date ASC, created_at ASC, id ASC
LIMIT 1
